import { DeleteObjectsCommand, PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { mkdir, rm, writeFile } from 'node:fs/promises';
import { dirname, resolve, sep } from 'node:path';
import type { Env } from '../config/env';

/** Object storage abstraction. Keys are always generated by the server, never taken from user input. */
export interface StorageDriver {
  put(key: string, body: Buffer, contentType: string): Promise<void>;
  remove(keys: string[]): Promise<void>;
  publicUrl(key: string): string;
}
export const STORAGE = Symbol('STORAGE');

const SAFE_KEY = /^[a-z0-9][a-z0-9/._-]*$/i;
function assertKey(key: string): void {
  if (!SAFE_KEY.test(key) || key.includes('..')) throw new Error('Unsafe storage key');
}

export class LocalStorageDriver implements StorageDriver {
  readonly root: string;
  constructor(dir: string, private readonly baseUrl: string) {
    this.root = resolve(dir);
  }
  private path(key: string): string {
    assertKey(key);
    const full = resolve(this.root, key);
    if (!full.startsWith(this.root + sep)) throw new Error('Unsafe storage key');
    return full;
  }
  async put(key: string, body: Buffer): Promise<void> {
    const file = this.path(key);
    await mkdir(dirname(file), { recursive: true });
    await writeFile(file, body);
  }
  async remove(keys: string[]): Promise<void> {
    await Promise.all(keys.map((k) => rm(this.path(k), { force: true })));
  }
  publicUrl(key: string): string {
    return `${this.baseUrl.replace(/\/$/, '')}/${key}`;
  }
}

/** Works with AWS S3, Cloudflare R2, DigitalOcean Spaces, Backblaze B2, MinIO. */
export class S3StorageDriver implements StorageDriver {
  private readonly client: S3Client;
  constructor(private readonly env: Env) {
    this.client = new S3Client({
      region: env.S3_REGION,
      endpoint: env.S3_ENDPOINT,
      forcePathStyle: env.S3_FORCE_PATH_STYLE,
      credentials: { accessKeyId: env.S3_ACCESS_KEY_ID!, secretAccessKey: env.S3_SECRET_ACCESS_KEY! },
    });
  }
  async put(key: string, body: Buffer, contentType: string): Promise<void> {
    assertKey(key);
    await this.client.send(new PutObjectCommand({
      Bucket: this.env.S3_BUCKET, Key: key, Body: body, ContentType: contentType,
      CacheControl: 'public, max-age=31536000, immutable',
    }));
  }
  async remove(keys: string[]): Promise<void> {
    if (!keys.length) return;
    keys.forEach(assertKey);
    await this.client.send(new DeleteObjectsCommand({ Bucket: this.env.S3_BUCKET, Delete: { Objects: keys.map((Key) => ({ Key })) } }));
  }
  publicUrl(key: string): string {
    return `${this.env.STORAGE_PUBLIC_URL.replace(/\/$/, '')}/${key}`;
  }
}

export function createStorage(env: Env): StorageDriver {
  return env.STORAGE_DRIVER === 's3' ? new S3StorageDriver(env) : new LocalStorageDriver(env.STORAGE_LOCAL_DIR, env.STORAGE_PUBLIC_URL);
}
